/**
 * The OSM navigation map's data (data/shuk-map-nahlaot-*.json, generated by scripts/map/build-shuk-map.mjs) and the
 * conversion between real-world positions and map units. Pure: the projection is passed in, so every frame (small,
 * large, a future Mahane Yehuda frame) uses the same functions. The maths mirrors the build script's, and the DORI
 * platform's data/places-old-city-map.ts, from which it was copied (Tour-Tech/TourTechToolBox, ddf0b38).
 */

/** A local equirectangular projection around the frame's centre: metres east and south, then a uniform scale. */
export type OsmMapProjection = Readonly<{
  kind: "local-equirectangular";
  lat0: number;
  lon0: number;
  mPerDegLat: number;
  mPerDegLon: number;
  minX: number;
  minY: number;
  unitsPerMetre: number;
}>;

/** Path data for one layer, split into what is inside the frame and what is in the faded margin. */
export type FramedPaths = Readonly<{ inside: string; outside: string }>;

/** One street's names. `he`/`en` are null where OSM has none (see docs/map/nahlaot-street-names.md). */
export type OsmMapName = Readonly<{ he: string | null; en: string | null; checkedOnSite: boolean; inFrame: boolean }>;

/** A named park, square, market or synagogue outline, labelled at its centre; `alt` holds a name the owner added. */
export type OsmMapPlace = Readonly<{
  osm: string;
  kind: "market" | "worship" | "square" | "green";
  he: string | null;
  en: string | null;
  alt?: Readonly<{ he?: string; en?: string }>;
  x: number;
  y: number;
  inFrame?: false;
}>;

/** An OSM neighbourhood name, or a courtyard the owner placed (source "owner, …"). */
export type OsmMapNeighbourhood = Readonly<{
  he: string | null;
  en: string | null;
  heDraft?: true;
  lat: number;
  lon: number;
  x: number;
  y: number;
  scale: "neighbourhood" | "courtyard";
  source: string;
  osm?: string;
  inFrame?: false;
}>;

/** A map-layer feature drawn as an icon (owner, 11 Nov 2026), from OSM outlines and points merged into one each. */
export type OsmMapPoi = Readonly<{
  kind: "synagogue" | "toilets" | "drinkingWater" | "tram";
  he: string | null;
  en: string | null;
  x: number;
  y: number;
  osm: ReadonlyArray<string>;
  inFrame?: false;
}>;

/** A road class at one real width (metres), drawn as a band `drawM` wide (main roads wider than real). */
export type OsmMapRoad = Readonly<{ class: "main" | "street" | "path"; widthM: number; drawM: number; inside: string; outside: string }>;

/**
 * One label, from data/shuk-map-nahlaot-<frame>.labels-<lang>.json. Shown from `minZoom` (Leaflet CRS.Simple zoom:
 * 2^z pixels per map unit) up to `maxZoom` if set. `w`/`h` are its size in screen pixels, `angle` in degrees (upright).
 * It refers to `names` (n), `places` (p) or `neighbourhoods` (nb) in the map data. `run` is the straight stretch it sits
 * on (map units) and `roadM` the road's drawn width, for street labels. `mainBrief` is a main road's zoomed-out label
 * (the game's language only, one zoom step), inside the road or, with `beside`, next to it. `poi` is a map-layer icon
 * (`pois[poi]`, no text) and `poiName` its name beside it, placed afresh at each zoom step.
 */
export type OsmMapLabel = Readonly<{
  kind: "main" | "mainBrief" | "alley" | "place" | "neighbourhood" | "courtyard" | "poi" | "poiName";
  text: ReadonlyArray<string>;
  n?: number;
  p?: number;
  nb?: number;
  poi?: number;
  x: number;
  y: number;
  angle: number;
  w: number;
  h: number;
  minZoom: number;
  maxZoom?: number;
  run?: number;
  roadM?: number;
  beside?: true;
  inFrame?: false;
}>;

export type OsmMapLabelStyle = Readonly<{ fontPx?: number; iconPx?: number; minRoadPx?: number; gapPx?: number; fit?: number; altFontPx?: number; letterPx?: number; zooms?: readonly [number, number] }>;

export type OsmMapLabelFile = Readonly<{
  meta: Readonly<{
    note: string; credit: string; creditUrl: string; licence: string; frame: string; lang: "en" | "he";
    zooms: ReadonlyArray<number>;
    // At this zoom every text size is multiplied by `scale`, and the labels there are laid out on their own.
    streetLevel: Readonly<{ zoom: number; scale: number }>;
    styles: Readonly<{ main: OsmMapLabelStyle; mainBrief: OsmMapLabelStyle; alley: OsmMapLabelStyle; place: OsmMapLabelStyle; neighbourhood: OsmMapLabelStyle; courtyard: OsmMapLabelStyle; poi: OsmMapLabelStyle; poiName: OsmMapLabelStyle; lineHeight: number; marginPx: number; repeatPx: number; maxBendDeg: number }>;
    unplaced: ReadonlyArray<Readonly<{ kind: OsmMapLabel["kind"]; text: ReadonlyArray<string> }>>;
    noNameInLanguage: ReadonlyArray<string>;
  }>;
  labels: ReadonlyArray<OsmMapLabel>;
}>;

export type OsmMapGeometry = Readonly<{
  meta: Readonly<{ note: string; credit: string; creditUrl: string; licence: string; extract: string; extractDate: string; frameSetBy: string }>;
  frame: Readonly<{ id: string; title: string; outline: string; edges: ReadonlyArray<Readonly<{ streets: string[]; osm: string[]; metres: number }>> }>;
  projection: OsmMapProjection;
  artboard: Readonly<{ width: number; height: number }>;
  areas: Readonly<{ market: string; worship: string; square: string; green: string }>;
  buildings: FramedPaths;
  roads: ReadonlyArray<OsmMapRoad>;
  names: ReadonlyArray<OsmMapName>;
  places: ReadonlyArray<OsmMapPlace>;
  neighbourhoods: ReadonlyArray<OsmMapNeighbourhood>;
  pois: ReadonlyArray<OsmMapPoi>;
}>;

export type MapPoint = Readonly<{ x: number; y: number }>;
export type GeoPosition = Readonly<{ lat: number; lon: number }>;

/** A real-world position to map units (x east, y south). Exact to OSM's accuracy: the map is drawn with the same maths. */
export function geoToMap(projection: OsmMapProjection, lat: number, lon: number): MapPoint {
  const mx = (lon - projection.lon0) * projection.mPerDegLon;
  const my = (projection.lat0 - lat) * projection.mPerDegLat;
  return { x: (mx - projection.minX) * projection.unitsPerMetre, y: (my - projection.minY) * projection.unitsPerMetre };
}

/** Map units back to a real-world position, e.g. for an "Open in Google Maps" link. */
export function mapToGeo(projection: OsmMapProjection, x: number, y: number): GeoPosition {
  const mx = x / projection.unitsPerMetre + projection.minX;
  const my = y / projection.unitsPerMetre + projection.minY;
  return { lat: projection.lat0 - my / projection.mPerDegLat, lon: projection.lon0 + mx / projection.mPerDegLon };
}

/** A distance on the ground in map units (e.g. a GPS accuracy circle). */
export function metresToUnits(projection: OsmMapProjection, metres: number): number {
  return metres * projection.unitsPerMetre;
}
